import type React from "react"
import { useEffect, useId, useMemo, useRef, useState } from "react"
import {
  ArrowUpRight,
  Hash,
  Link2,
  Printer,
  Search,
  SunMoon,
  type LucideIcon,
} from "lucide-react"
import { socials } from "@/components/social-icons"
import { humance } from "@/data/profile"
import { toggleTheme } from "@/hooks/use-theme"

interface CommandBase {
  id: string
  label: string
  group: string
  icon: LucideIcon
}

// `run` fires after the palette closes. `runWithStatus` fires while it is still
// open, so the palette can announce the resolved message before closing.
type Command = CommandBase &
  ({ run: () => void } | { runWithStatus: () => Promise<string> })

const STATUS_CLOSE_DELAY_MS = 1200

const sections = [
  ["about", "About"],
  ["experience", "Experience"],
  ["products", "Products"],
  ["skills", "Skills"],
  ["beyond", "Beyond the code"],
  ["contact", "Contact"],
] as const

const openExternal = (url: string) =>
  window.open(url, "_blank", "noopener,noreferrer")

// Assigning location.hash is a no-op when the hash already matches, so the home
// page scrolls explicitly; any other page (the 404) loads the home section.
const goToSection = (id: string) => {
  if (window.location.pathname !== "/") {
    window.location.href = `/#${id}`
    return
  }
  document.getElementById(id)?.scrollIntoView()
  history.replaceState(null, "", `#${id}`)
}

// Command ids end up in DOM ids referenced by aria-activedescendant, which must
// not contain whitespace.
const slugify = (text: string) =>
  text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")

const canCopyLink =
  typeof navigator !== "undefined" &&
  typeof navigator.clipboard?.writeText === "function"

const copyLinkCommand: Command = {
  id: "copy-link",
  label: "Copy page link",
  group: "Actions",
  icon: Link2,
  runWithStatus: () =>
    navigator.clipboard.writeText(`${window.location.origin}/`).then(
      () => "Link copied",
      () => "Copy failed"
    ),
}

const commands: Command[] = [
  ...sections.map(([id, label]) => ({
    id: `go-${id}`,
    label: `Go to ${label}`,
    group: "Navigate",
    icon: Hash,
    run: () => goToSection(id),
  })),
  ...socials.map(({ label, href }) => ({
    id: `open-${slugify(label)}`,
    label: `Open ${label}`,
    group: "Links",
    icon: ArrowUpRight,
    run: () => openExternal(href),
  })),
  ...humance.products.map(({ name, url }) => ({
    id: `visit-${slugify(name)}`,
    label: `Visit ${name}`,
    group: "Links",
    icon: ArrowUpRight,
    run: () => openExternal(url),
  })),
  {
    id: "theme",
    label: "Toggle light / dark theme",
    group: "Actions",
    icon: SunMoon,
    run: toggleTheme,
  },
  {
    id: "print",
    label: "Print résumé",
    group: "Actions",
    icon: Printer,
    run: () => window.print(),
  },
  ...(canCopyLink ? [copyLinkCommand] : []),
]

interface CommandPaletteProps {
  open: boolean
  onClose: () => void
}

export const CommandPalette = ({ open, onClose }: CommandPaletteProps) => {
  const dialogRef = useRef<HTMLDialogElement>(null)
  const pointerDownOnBackdrop = useRef(false)
  const [query, setQuery] = useState("")
  const [activeIndex, setActiveIndex] = useState(0)
  const [actionStatus, setActionStatus] = useState("")
  const listId = useId()

  const results = useMemo(() => {
    const term = query.trim().toLowerCase()
    return term
      ? commands.filter((c) => c.label.toLowerCase().includes(term))
      : commands
  }, [query])

  useEffect(() => {
    const dialog = dialogRef.current
    if (!dialog) return
    if (open && !dialog.open) dialog.showModal()
    if (!open && dialog.open) dialog.close()
  }, [open])

  useEffect(() => {
    if (!actionStatus) return
    const timer = window.setTimeout(
      () => dialogRef.current?.close(),
      STATUS_CLOSE_DELAY_MS
    )
    return () => window.clearTimeout(timer)
  }, [actionStatus])

  const handleClose = () => {
    setQuery("")
    setActiveIndex(0)
    setActionStatus("")
    onClose()
  }

  const optionId = (command: Command) => `${listId}-${command.id}`

  const runCommand = (command: Command) => {
    if ("runWithStatus" in command) {
      void command.runWithStatus().then((message) => {
        if (dialogRef.current?.open) setActionStatus(message)
      })
      return
    }
    dialogRef.current?.close()
    command.run()
  }

  const onKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (results.length === 0) return
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault()
      const step = event.key === "ArrowDown" ? 1 : -1
      const next = (activeIndex + step + results.length) % results.length
      setActiveIndex(next)
      document
        .getElementById(optionId(results[next]))
        ?.scrollIntoView({ block: "nearest" })
    } else if (event.key === "Enter") {
      event.preventDefault()
      runCommand(results[activeIndex])
    }
  }

  const active = results[activeIndex]
  const statusMessage =
    actionStatus || (results.length === 0 ? "No matching commands" : "")

  return (
    <dialog
      ref={dialogRef}
      aria-label="Command menu"
      onClose={handleClose}
      // Close only when the press also started on the backdrop, so a text
      // selection dragged out of the panel does not dismiss it.
      onPointerDown={(event) => {
        pointerDownOnBackdrop.current = event.target === event.currentTarget
      }}
      onClick={(event) => {
        if (
          pointerDownOnBackdrop.current &&
          event.target === event.currentTarget
        ) {
          event.currentTarget.close()
        }
      }}
      className="m-auto mt-[12vh] w-[min(36rem,calc(100vw-2rem))] overflow-hidden rounded-2xl border border-line bg-surface p-0 text-ink-soft shadow-2xl backdrop:bg-slate-950/60 backdrop:backdrop-blur-sm"
    >
      <div className="flex items-center gap-3 border-b border-line px-4">
        <Search
          aria-hidden="true"
          strokeWidth={2}
          className="size-4 text-ink-muted"
        />
        <input
          autoFocus
          type="text"
          role="combobox"
          aria-label="Search commands"
          aria-expanded="true"
          aria-controls={listId}
          aria-autocomplete="list"
          aria-activedescendant={active ? optionId(active) : undefined}
          value={query}
          onChange={(event) => {
            setQuery(event.target.value)
            setActiveIndex(0)
          }}
          onKeyDown={onKeyDown}
          placeholder="Type a command or search…"
          className="h-14 flex-1 bg-transparent text-ink outline-none placeholder:text-ink-muted"
        />
        <kbd className="rounded-md border border-line px-1.5 py-0.5 font-sans text-xs text-ink-muted">
          Esc
        </kbd>
      </div>

      <ul
        id={listId}
        role="listbox"
        aria-label="Commands"
        className="max-h-[50vh] overflow-y-auto p-2"
      >
        {results.map((command, index) => {
          const isActive = index === activeIndex
          return (
            <li
              key={command.id}
              id={optionId(command)}
              role="option"
              aria-selected={isActive}
              onClick={() => runCommand(command)}
              onMouseMove={() => setActiveIndex(index)}
              className={`flex cursor-pointer items-center gap-3 rounded-xl px-3 py-2.5 text-sm ${
                isActive ? "bg-ink/[0.06] text-ink" : "text-ink-soft"
              }`}
            >
              <command.icon
                aria-hidden="true"
                strokeWidth={1.75}
                className="size-4 text-accent"
              />
              {command.label}
              <span
                aria-hidden="true"
                className="ml-auto text-xs text-ink-muted"
              >
                {command.group}
              </span>
            </li>
          )
        })}
      </ul>
      <p
        role="status"
        className="px-3 text-center text-sm text-ink-muted [&:not(:empty)]:py-6"
      >
        {statusMessage}
      </p>
    </dialog>
  )
}
